<script setup lang="ts">
import {ref} from 'vue';import {useRoute} from 'vue-router';import {api,post,type Run,type Reconciliation} from '../api';import {usePoll} from '../composables/poll';import {useAuth} from '../stores/auth';import {money,time} from '../money';import DataState from '../components/DataState.vue';import StatusBadge from '../components/StatusBadge.vue';
const auth=useAuth();const selected=ref(String(useRoute().query.run??''));const grace=ref(30);const report=ref<Reconciliation>();const busy=ref(false);const error=ref('');const runs=usePoll(signal=>api<Run[]>('/runs',{signal}));
async function reconcile(){busy.value=true;error.value='';try{report.value=await api<Reconciliation>(`/reconciliation/${selected.value}?graceSeconds=${grace.value}`)}catch(e){error.value=e instanceof Error?e.message:'Reconciliation unavailable'}finally{busy.value=false}}
async function recover(id:string){busy.value=true;error.value='';try{await post(`/transactions/${id}/redeliver`);await reconcile()}catch(e){error.value=e instanceof Error?e.message:'Recovery failed'}finally{busy.value=false}}
</script>
<template><div class="page-title"><div><p class="eyebrow">BANK SETTLEMENT ↔ LMS LEDGER</p><h1>Reconciliation</h1><p class="muted">Compare successful unique bank transactions by identity, count and amount.</p></div></div><DataState :loading="runs.loading.value" :error="runs.error.value" :updated-at="runs.updatedAt.value"/><el-alert v-if="error" :title="error" type="error" :closable="false"/><section class="panel"><div class="panel-heading"><div><h3>Choose a settlement report</h3><p>A processing grace period distinguishes missing receipts from in-flight work.</p></div></div><div class="reconcile-controls"><label>Simulator run<el-select v-model="selected" placeholder="Select run"><el-option v-for="r in runs.data.value??[]" :key="r.id" :value="r.id" :label="r.preset+' · '+time(r.createdAt)"/></el-select></label><label>Grace period (seconds)<el-input-number v-model="grace" :min="5" :max="300"/></label><el-button type="primary" :disabled="!selected" :loading="busy" @click="reconcile">Compare settlement</el-button></div></section>
<template v-if="report"><div class="stat-grid"><div v-for="s in ['Matched','NotYetApplied','MissingReceipt','UnmatchedReference','AmountConflict','OutcomeConflict']" :key="s" class="stat-card"><span>{{s.replace(/([a-z])([A-Z])/g,'$1 $2')}}</span><strong>{{report.counts[s]??0}}</strong><small>{{money(report.totals[s]??'0')}}</small></div></div><section class="panel"><div class="panel-heading"><div><h3>Settlement differences & matches</h3><p>Cutoff {{time(report.cutoff)}} · {{report.graceSeconds}}s grace · at most {{report.sampleLimit}} displayed rows. Totals include all transactions.</p></div></div><el-table :data="report.items"><el-table-column prop="bankTransactionId" label="Original bank identity" min-width="290"/><el-table-column prop="paymentReference" label="Loan reference" width="170"/><el-table-column label="Bank amount" min-width="170"><template #default="{row}">{{money(row.amountMinor)}}</template></el-table-column><el-table-column label="Comparison" min-width="180"><template #default="{row}"><StatusBadge :status="row.status"/></template></el-table-column><el-table-column v-if="auth.role==='Admin'" label="Audited recovery" width="180"><template #default="{row}"><el-button v-if="row.status==='MissingReceipt'" size="small" :disabled="busy" @click="recover(row.bankTransactionId)">Redeliver original</el-button></template></el-table-column></el-table><p class="chart-note">Duplicates do not increase successful bank transaction counts. Redelivery preserves event ID, transaction ID, body and bank paidAt.</p></section></template><el-empty v-else description="Select a recorded run to compare its persisted settlement report."/></template>
